/**
 * Local Parce - Marked.js Library Wrapper
 *
 * AMD wrapper for the marked.js markdown parser library.
 * This module exposes the marked global object to AMD module system.
 *
 * @module     local_parce/lib-marked
 * @copyright  2026 David Herney @ BambuCo
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

// Define an AMD module that loads the marked library
require.config({
    paths: {
        'marked-lib': M.cfg.wwwroot + '/local/parce/lib/marked/marked.min'
    }
});

define('local_parce/lib-marked', ['marked-lib', 'core/log'], function(marked, Log) {
    'use strict';

    // The marked library is loaded globally, return the marked object
    // In the global scope after loading marked.min.js
    if (typeof window !== 'undefined' && window.marked) {
        return {
            marked: window.marked
        };
    }

    // Fallback error
    Log.debug('Marked library could not be loaded');
    return {
        marked: null
    };
});
